    public static string Text(StarterCard c)
    {
        var s=Cards[c.SourceCardId];return (c.IsUpgraded?s.Upgraded:s.Normal)+(c.PrintedManaCost>0?$"\n契约魔力费用：{c.PrintedManaCost}。":"");
    }
    static MegaCrit.Sts2.Core.HoverTips.IHoverTip Tip(string title,string description)=>new MegaCrit.Sts2.Core.HoverTips.HoverTip(EconomyNativeUi.Text(title),description){Id="FSN_CARD_TIP_"+title};
    public static IEnumerable<MegaCrit.Sts2.Core.HoverTips.IHoverTip> Tips(StarterCard c)
    {
        var id=c.SourceCardId;
        if(c.Type==CardType.Power)yield return Tip("同名能力","同名能力只保留最高等级，效果不叠加，也不刷新次数。手动打出重复副本时，每次额外抽1张所属成员的牌；自动打出与重复结算不获得此补偿。");
        if(c.HasJewelChoice||id is "RIN-R04" or "RIN-R06")yield return Tip("宝石强化","打出前可选择花费1枚宝石，改用强化效果。取消不花费资源。免费强化仍需持有宝石。直接花费宝石的效果不属于宝石强化。");
        if(id is "ARC_S_COVER" or "RIN-C08" or "RIN-C15" or "RIN-U12" or "RIN-U14" or "ARC-U12" or "ARC-U16")yield return Tip("整理手牌","将所选成员的手牌弃置，再抽等量牌；后备也可整理。选择不整理时不产生弃牌或抽牌；抽牌仍受手牌上限及禁抽效果限制。");
        if(id is "RIN_S_REINFORCE_PROJECTION" or "RIN-U10")yield return Tip("兵装强化","强化投影优先于投影强化术式：成功生成一件兵装只使用一种强化来源，优先来源生效时不扣术式次数。等待效果可跨回合保留；手牌已满等生成失败不会消耗等待效果。");
        if(id is "ARC-U01" or "ARC-U02" or "ARC-U14" or "ARC-R03" or "ARC-R06")yield return Tip("成功使用兵装","正常打出兵装、幻想崩坏或高阶幻想崩坏都计为成功使用；仅投影、保留、弃置或舍弃投影不计入。不同兵装按种类计算，每场战斗重置。");
        if(id is "RIN-R06" or "ARC-R06")yield return Tip("成长与伤害","本次效果先使用原有层数，结算后再获得新层数。每回合首次事件即使发生在能力生效前，也不会在该回合重新计数。额外伤害按整张牌总额分到各段，不逐段倍增；层数在战斗结束后清空。");
        if(id is "ARC-U13" or "ARC-R05")yield return Tip("独立行动","每回合首次使基础契约魔力费用为1、当前费用仍为1的弓兵牌，契约魔力费用降为0。不减少能量；其他减免已经令费用为0时，不消耗本次机会。");
        if(id is "RIN-C21" or "ARC-U21" or "RIN-R12")yield return Tip("状态转移","只转移虚弱、易伤、脆弱和中毒，保留来源、层数和剩余生命周期。目标免疫或已有同类状态的来源/生命周期不兼容时不转移。后备仍承受中毒和状态流逝，任一成员死亡都会失败。");
        if(id is "RIN-U20" or "ARC-U22")yield return Tip("生命支付","另一名成员失去真实生命，格挡不能抵扣。支付会令其死亡时不能使用；后备同样能支付。");
        if(id=="RIN-R11")yield return Tip("指数强化","倍率从1开始，每次成功宝石强化后翻倍。只放大直接基础伤害或格挡总额，再进行原生力量、虚弱等修正；不放大资源或触发次数。仅在原生数值边界饱和并提示。");
        if(id is "ARC-R10" or "ARC-R12")yield return Tip("累计兵装","正常使用与幻想崩坏按实际成功次数累计，同种兵装可重复计数。投影、弃置与舍弃不计入。连环幻想崩坏以本次材料消耗前的次数结算。");
        if(id=="ARC-C14")yield return Tip("护卫御主","弓兵代替凛承受下一次攻击伤害，使用弓兵自己的格挡。弓兵处于后备也能护卫。只保护原本指向凛的伤害，不保护直接指向弓兵的攻击或生命流失；多段攻击只挡一次。下个己方回合开始时失效，重复获得不叠加。");
        if(id=="ARC-U05")yield return Tip("精密射击","对普通敌人可选择任一存活目标；面对敌方契约，可选择前排或已有负面状态的后备。附加伤害合并到本次伤害中。");
        else if(c.Type==CardType.Attack||id is "RIN-C04" or "RIN-C10" or "RIN-U04" or "RIN-U06" or "RIN-U14" or "ARC-U02" or "ARC-R03")yield return Tip("前排与目标","对普通敌人可选择任一存活目标；面对敌方契约，前排是其当前出战成员。每段攻击保持同一目标，目标死亡后不换目标。赤原猎犬及高阶赤原猎犬可选择敌方契约的前排或后备。");
    }
}
